    '\n  *[_type == "marketingPage" && slug.current == $slug && ($preview == true || status == "published")][0] {\n    _id,\n    title,\n    slug,\n    status,\n    sections[] {\n      _type,\n      _key,\n      eyebrow,\n      headline,\n      subheadline,\n      primaryCta { label, href },\n      image { asset->{ url }, alt },\n      heading,\n      features[] { title, description, icon },\n      content,\n      quote,\n      name,\n      role,\n      avatar { asset->{ url } },\n      body,\n      buttonLabel,\n      buttonHref\n    },\n    metaTitle,\n    metaDescription\n  }\n': MarketingPageBySlugQueryResult;
    '\n  *[_type == "marketingPage" && status == "published" && defined(slug.current)].slug.current\n': MarketingPageSlugsQueryResult;
    '\n  *[_type == "homepageCaseStudySlider"][0] {\n    sectionEnabled,\n    slides[] {\n      company,\n      eyebrow,\n      title,\n      description,\n      ctaText,\n      ctaHref,\n      image { asset->{ url }, alt },\n      badgeImage { asset->{ url }, alt },\n      stats[] { value, label },\n      caseStudy-> {\n        client,\n        heroHeadline,\n        heroEyebrow,\n        headerTitle,\n        excerpt,\n        "slug": slug.current,\n        mainImage { asset->{ url }, alt },\n        highlights[] { value, label },\n        metrics[] { value, label }\n      }\n    }\n  }\n': HomepageCaseStudySliderQueryResult;
    '\n  *[_type == "globalSettings"][0] {\n    siteName,\n    siteUrl,\n    logo { asset->{ url }, alt },\n    defaultMetaTitle,\n    defaultMetaDescription,\n    socialLinks { linkedin, twitter, github, clutch },\n    contactInfo { email, phone, address },\n    analytics { gtmId, gaId, posthogKey },\n    designTokens { accentPreset, typographyPreset }\n  }\n': GlobalSettingsQueryResult;
    '\n  *[_type == "careersPage"][0] {\n    _id,\n    title,\n    heroEyebrow,\n    heroHeadline,\n    heroHeadlineItalic,\n    heroSubline,\n    heroCyclingRoles,\n    heroGallery[]{\n      "url": asset->url,\n      alt,\n      caption\n    },\n    introBadge,\n    introHeading,\n    introHighlight,\n    introBody,\n    introStats,\n    introPillars,\n    jobsHeading,\n    jobsSubheading,\n    jobsCategories,\n    jobs[]{\n      title,\n      category,\n      location,\n      type,\n      experience,\n      salary,\n      badge,\n      description,\n      tags\n    },\n    processHeading,\n    processSubheading,\n    processSteps,\n    perksHeading,\n    perksSubheading,\n    perks,\n    cultureHeading,\n    cultureSubheading,\n    cultureGallery[]{\n      "url": asset->url,\n      alt,\n      caption\n    },\n    culturePillars,\n    talentHeading,\n    talentBody,\n    talentEmail,\n    faqs,\n    metaTitle,\n    metaDescription\n  }\n': CareersPageQueryResult;
    '\n  *[_type == "caseStudy" && coalesce(status, "published") == "published" && slug.current in [\n    "ai-website-performance-monitoring",\n    "barcode-scanner-app-audio-equipment-management",\n    "ai-driven-itsm-analytics-platform-microsoft-fabric",\n    "enterprise-leave-management-system"\n  ]] {\n    _id,\n    title,\n    client,\n    slug,\n    excerpt,\n    storyType,\n    heroLayout,\n    detailLayout,\n    industry,\n    useCase,\n    companySize,\n    featuredRank,\n    mainImage { asset->{ url }, alt },\n    mainImageUrl,\n    "keyResults": keyResults[] { value, label, description }\n  }\n': HomepageFeaturedCaseStudiesQueryResult;
